/* =========================================================
   RAMIS SHOP — PREMIUM COMPACT CART
   Primary : #006660
   Accent  : #FFCE3A
========================================================= */


/* ---------------------------------------------------------
   کانتینر اصلی
--------------------------------------------------------- */

selector .header-cart {
    position: relative;
    display: inline-flex;
    align-items: center;
}


/* ---------------------------------------------------------
   دکمه اصلی سبد خرید
--------------------------------------------------------- */

selector .header-cart .cart-contents {
    position: relative;
    width: 48px;
    height: 48px;
    min-width: 48px;
    padding: 0 !important;

    display: flex;
    align-items: center;
    justify-content: center;

    background: #006660 !important;
    border-radius: 15px !important;

    text-decoration: none !important;

    box-shadow: 0 8px 22px rgba(0, 102, 96, 0.16);

    transition:
        transform 0.3s ease,
        background 0.3s ease,
        box-shadow 0.3s ease;
}


/* ---------------------------------------------------------
   آیکون
--------------------------------------------------------- */

selector .header-cart .cart-contents .icon {
    display: flex;
    align-items: center;
    justify-content: center;
}

selector .header-cart .cart-contents .icon i {
    color: #ffffff !important;
    font-size: 20px;
    line-height: 1;

    transition:
        transform 0.3s ease,
        color 0.3s ease;
}


/* ---------------------------------------------------------
   مخفی کردن متن «سبد خرید»
--------------------------------------------------------- */

selector .header-cart .cart-contents .detail .title {
    display: none !important;
}


/* ---------------------------------------------------------
   جلوگیری از کشیده شدن بخش اطلاعات
--------------------------------------------------------- */

selector .header-cart .cart-contents .detail {
    position: static !important;
    display: block !important;
}


/* ---------------------------------------------------------
   Badge تعداد محصولات
--------------------------------------------------------- */

selector .header-cart .cart-contents .count {
    position: absolute !important;

    top: 1px;
    right: -10px;

    width: 20px;
    height: 20px;
    min-width: 20px;

    display: flex !important;
    align-items: center;
    justify-content: center;

    padding: 0 !important;

    background: #FFCE3A !important;
    color: #006660 !important;

    border-radius: 50% !important;

    font-size: 11px !important;
    font-weight: 800;
    line-height: 1 !important;

    box-shadow: 0 4px 10px rgba(0, 0, 0, 0.12);

    z-index: 5;
}


/* =========================================================
   HOVER
========================================================= */

selector .header-cart .cart-contents:hover {
    background: #004F4B !important;

    transform: translateY(-3px);

    box-shadow: 0 14px 28px rgba(0, 102, 96, 0.24);
}

selector .header-cart .cart-contents:hover .icon i {
    color: #FFCE3A !important;
    transform: scale(1.08);
}


/* ---------------------------------------------------------
   حالت کلیک
--------------------------------------------------------- */

selector .header-cart .cart-contents:active {
    transform: translateY(-1px) scale(0.96);
}


/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 767px) {

    selector .header-cart .cart-contents {
        width: 44px;
        height: 44px;
        min-width: 44px;

        border-radius: 15px !important;
    }

    selector .header-cart .cart-contents .icon i {
        font-size: 18px;
    }

    selector .header-cart .cart-contents .count {
        width: 18px;
        height: 18px;
        min-width: 18px;

        font-size: 10px !important;

        top: -5px;
        right: -5px;
    }
}

/* RAMIS SHOP — ACCOUNT BORDER */

selector .header-account > a {
    display: flex;
    align-items: center;
    justify-content: center;

    width: 48px;
    height: 48px;

    padding: 2px;
    box-sizing: border-box;

    border: 2px solid #FFCE3A;
    border-radius: 15px;

    overflow: hidden;

    transition: all 0.3s ease;
}

selector .header-account > a figure {
    width: 100%;
    height: 100%;
    margin: 0;

    display: flex;
    align-items: center;
    justify-content: center;
}

selector .header-account > a img {
    width: 100%;
    height: 100%;

    object-fit: cover;
    border-radius: 12px;
}


/* Hover */

selector .header-account > a:hover {
    border-color: #006660;
    transform: translateY(-3px);
}


/* Mobile */

@media (max-width: 767px) {

    selector .header-account > a {
        width: 44px;
        height: 44px;
        border-radius: 15px;
    }

    selector .header-account > a img {
        border-radius: 12px;
    }
}

