/* =========================================================
   RAMIS — CART MINI POPUP FIX
   رفع مشکل رفتن پاپ‌آپ سبد خرید زیر آیتم‌های هدر
========================================================= */

/* خود ویجت و سبد در بالاترین لایه */
selector,
selector .elementor-widget-container,
selector .pooshe-elementor-widget,
selector .header-cart {
    position: relative;
    z-index: 9999;
}

/* پاپ‌آپ / مینی کارت */
selector .widget_shopping_cart_content {
    position: absolute !important;
    z-index: 99999 !important;
}

/* هنگام هاور، کل سبد بالاتر از بقیه هدر قرار بگیرد */
selector:hover {
    z-index: 99999 !important;
}

/* =========================================================
   MOBILE FIX
========================================================= */

@media (max-width: 767px) {

    selector,
    selector .elementor-widget-container,
    selector .pooshe-elementor-widget,
    selector .header-cart {
        overflow: visible !important;
    }

    selector .widget_shopping_cart_content {
        z-index: 999999 !important;
    }
}
